import { useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { getGap, listGaps, updateGapStatus } from "@/api/gaps";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { ArrowLeft, BookOpen, GitBranch, Lightbulb, BarChart3 } from "lucide-react";
import { GapFeedbackForm } from "@/components/gaps/gap-feedback-form";
import type { ResearchGap } from "@/api/types";

/** Gap type badge color mapping. */
const GAP_TYPE_COLORS: Record<string, string> = {
  methodological: "bg-blue-100 text-blue-800",
  empirical: "bg-green-100 text-green-800",
  theoretical: "bg-purple-100 text-purple-800",
  "cross-domain": "bg-orange-100 text-orange-800",
};

export default function GapDetailPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const gapId = Number(id);

  const { data, isLoading, isError } = useQuery({
    queryKey: ["gap", gapId],
    queryFn: () => getGap(gapId),
    enabled: !isNaN(gapId),
  });

  const gap: ResearchGap | undefined = data?.gap;

  // Fetch related ideas (ideas that reference this gap's title)
  const { data: relatedIdeasData } = useQuery({
    queryKey: ["ideas-for-gap", gap?.title],
    queryFn: () =>
      listGaps({ search: gap?.title, limit: 5 } as Record<string, unknown>).catch(() => ({
        gaps: [],
        total: 0,
      })),
    enabled: !!gap?.title,
  });

  if (isLoading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-8 w-32" />
        <Skeleton className="h-10 w-3/4" />
        <Skeleton className="h-40 w-full" />
        <Skeleton className="h-24 w-full" />
      </div>
    );
  }

  if (isError || !gap) {
    return (
      <div className="space-y-4 text-center py-12">
        <GitBranch className="h-12 w-12 mx-auto text-muted-foreground opacity-50" />
        <h2 className="text-xl font-semibold">Gap not found</h2>
        <p className="text-muted-foreground">
          The research gap with ID {id} could not be found.
        </p>
        <Button variant="outline" onClick={() => navigate("/gaps")}>
          <ArrowLeft className="mr-2 h-4 w-4" />
          Back to Gaps Explorer
        </Button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <Button
          variant="ghost"
          size="sm"
          onClick={() => navigate("/gaps")}
          className="mb-2"
        >
          <ArrowLeft className="mr-1 h-4 w-4" />
          Back to Gaps
        </Button>
        <h1 className="text-2xl font-bold tracking-tight">{gap.title}</h1>
        <div className="flex items-center gap-3 mt-2">
          {/* Gap type badge */}
          <span
            className={`px-2.5 py-0.5 rounded-full text-xs font-medium ${
              GAP_TYPE_COLORS[gap.gap_type] || "bg-gray-100 text-gray-800"
            }`}
          >
            {gap.gap_type || "unknown"}
          </span>
          {/* Confidence */}
          <div className="flex items-center gap-2">
            <BarChart3 className="h-4 w-4 text-muted-foreground" />
            <div className="w-32 bg-gray-200 rounded-full h-2">
              <div
                className="bg-primary rounded-full h-2 transition-all"
                style={{ width: `${Math.round(gap.confidence * 100)}%` }}
              />
            </div>
            <span className="text-sm text-muted-foreground">
              {Math.round(gap.confidence * 100)}% confidence
            </span>
          </div>
          {/* Status dropdown (BATCH-41) */}
          <select
            value={gap.status || "identified"}
            onChange={async (e) => {
              try { await updateGapStatus(gapId, e.target.value); } catch {} 
            }}
            className="px-2 py-0.5 text-xs border rounded-md bg-background"
            aria-label="Gap lifecycle status"
          >
            <option value="identified">Identified</option>
            <option value="investigating">Investigating</option>
            <option value="addressed">Addressed</option>
          </select>
        </div>
      </div>

      {/* Description */}
      <div className="bg-card border rounded-lg p-4">
        <h2 className="text-lg font-semibold mb-2">Description</h2>
        <p className="text-muted-foreground whitespace-pre-wrap">
          {gap.description || "No description available."}
        </p>
        {gap.potential_impact && (
          <div className="mt-4 pt-4 border-t">
            <h3 className="text-sm font-medium mb-1">Potential Impact</h3>
            <p className="text-sm text-muted-foreground">{gap.potential_impact}</p>
          </div>
        )}
      </div>

      {/* Truth Values */}
      {gap.truth && (
        <div className="bg-card border rounded-lg p-4">
          <h2 className="text-lg font-semibold mb-3 flex items-center gap-2">
            <BookOpen className="h-5 w-5" />
            Truth Values
          </h2>
          <div className="grid grid-cols-3 gap-4">
            <div>
              <p className="text-xs text-muted-foreground">Frequency</p>
              <p className="text-lg font-medium">{parseFloat(String(gap.truth.frequency)).toFixed(3)}</p>
            </div>
            <div>
              <p className="text-xs text-muted-foreground">Confidence</p>
              <p className="text-lg font-medium">{parseFloat(String(gap.truth.confidence)).toFixed(3)}</p>
            </div>
            <div>
              <p className="text-xs text-muted-foreground">Evidence Count</p>
              <p className="text-lg font-medium">{gap.truth.evidence_count}</p>
            </div>
          </div>
        </div>
      )}

      {/* Cluster Membership */}
      {gap.related_clusters && gap.related_clusters.length > 0 && (
        <div className="bg-card border rounded-lg p-4">
          <h2 className="text-lg font-semibold mb-3 flex items-center gap-2">
            <GitBranch className="h-5 w-5" />
            Cluster Membership
          </h2>
          <div className="flex flex-wrap gap-2">
            {gap.related_clusters.map((clusterId) => (
              <span
                key={clusterId}
                className="px-3 py-1 bg-muted rounded-full text-sm font-medium"
              >
                Cluster {clusterId}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Related Ideas */}
      {gap.idea_count != null && gap.idea_count > 0 && (
        <div className="bg-card border rounded-lg p-4">
          <h2 className="text-lg font-semibold mb-3 flex items-center gap-2">
            <Lightbulb className="h-5 w-5" />
            Related Ideas
          </h2>
          <p className="text-sm text-muted-foreground">
            {gap.idea_count} idea{gap.idea_count !== 1 ? "s" : ""} linked to this gap.
          </p>
          <Button
            variant="outline"
            size="sm"
            className="mt-2"
            onClick={() => navigate(`/ideas?search=${encodeURIComponent(gap.title)}`)}
          >
            View Related Ideas
          </Button>
        </div>
      )}

      {/* Metadata */}
      <div className="text-xs text-muted-foreground">
        <p>Gap ID: {gap.id}</p>
        {gap.pipeline_run_id && <p>Pipeline Run: {gap.pipeline_run_id}</p>}
      </div>

      {/* Feedback Form (BATCH-41) */}
      <div className="bg-card border rounded-lg p-4">
        <GapFeedbackForm
          gapId={gap.id}
          currentRating={gap.user_rating}
          currentNotes={gap.user_notes}
        />
      </div>
    </div>
  );
}

/**
 * Memory Browser Page — BATCH-19/TASK-02
 *
 * Full Memory Browser page replacing the /memory placeholder.
 * Features: search input, type filter, delete confirmation,
 * memory cards list with stats header.
 */

import { useCallback, useEffect, useState } from "react";
import { getMemoryStats, recallMemories, deleteMemory } from "@/api/memory";
import type { MemoryStats as MemoryStatsData, MemoryRecallResult } from "@/api/memory";
import { MemoryCard } from "@/components/memory/memory-card";
import { MemoryStats } from "@/components/memory/memory-stats";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Search, Loader2, AlertCircle } from "lucide-react";

const MEMORY_TYPES = ["semantic", "episodic", "procedural"] as const;
const BROAD_QUERY = "*";
const DEFAULT_TOP_K = 50;

export default function MemoryBrowserPage() {
  const [stats, setStats] = useState<MemoryStatsData | null>(null);
  const [results, setResults] = useState<MemoryRecallResult[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [query, setQuery] = useState("");
  const [activeQuery, setActiveQuery] = useState(BROAD_QUERY);
  const [typeFilter, setTypeFilter] = useState<string>("all");

  // Delete confirmation state
  const [confirmDelete, setConfirmDelete] = useState<MemoryRecallResult | null>(null);

  // ── Load stats ─────────────────────────────────────────────────
  const loadStats = useCallback(async () => {
    try {
      const data = await getMemoryStats();
      setStats(data);
    } catch {
      // Stats are non-critical; don't block the page
    }
  }, []);

  // ── Recall memories ────────────────────────────────────────────
  const loadMemories = useCallback(
    async (searchQuery: string, memType?: string) => {
      setLoading(true);
      setError(null);
      try {
        const params: { memory_type?: string; top_k?: number } = {
          top_k: DEFAULT_TOP_K,
        };
        if (memType && memType !== "all") {
          params.memory_type = memType;
        }
        const data = await recallMemories(searchQuery || BROAD_QUERY, params);
        setResults(data.results);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to load memories");
        setResults([]);
      } finally {
        setLoading(false);
      }
    },
    [],
  );

  // ── Initial load ───────────────────────────────────────────────
  useEffect(() => {
    loadStats();
    loadMemories(BROAD_QUERY);
  }, [loadStats, loadMemories]);

  // ── Search handler ─────────────────────────────────────────────
  function handleSearch() {
    const q = query.trim() || BROAD_QUERY;
    setActiveQuery(q);
    loadMemories(q, typeFilter);
  }

  function handleKeyDown(e: React.KeyboardEvent) {
    if (e.key === "Enter") {
      handleSearch();
    }
  }

  // ── Type filter handler ────────────────────────────────────────
  function handleTypeChange(value: string) {
    setTypeFilter(value);
    loadMemories(activeQuery, value);
  }

  // ── Delete handler ─────────────────────────────────────────────
  function handleDeleteRequest(memory: MemoryRecallResult) {
    setConfirmDelete(memory);
  }

  async function handleDeleteConfirm() {
    if (!confirmDelete) return;

    try {
      await deleteMemory(confirmDelete.content);
      setResults((prev) => prev.filter((m) => m !== confirmDelete));
      // Refresh stats after deletion
      loadStats();
    } catch {
      // Silently ignore — item stays in list
    } finally {
      setConfirmDelete(null);
    }
  }

  function handleDeleteCancel() {
    setConfirmDelete(null);
  }

  // ── Render ─────────────────────────────────────────────────────
  return (
    <div className="space-y-6" data-testid="memory-page">
      <h1 className="text-2xl font-bold tracking-tight">Memory Browser</h1>

      {/* Stats Header */}
      {stats && (
        <div data-testid="stats-header">
          <MemoryStats stats={stats} />
        </div>
      )}

      {/* Search & Filter Bar */}
      <div className="flex gap-3 items-center" data-testid="search-bar">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search memories..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            className="pl-9"
            data-testid="search-input"
          />
        </div>
        <Select value={typeFilter} onValueChange={handleTypeChange}>
          <SelectTrigger className="w-[160px]" data-testid="type-filter">
            <SelectValue placeholder="All types" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All types</SelectItem>
            {MEMORY_TYPES.map((t) => (
              <SelectItem key={t} value={t}>
                {t.charAt(0).toUpperCase() + t.slice(1)}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Button onClick={handleSearch} data-testid="search-btn">
          Search
        </Button>
      </div>

      {/* Loading State */}
      {loading && (
        <div className="flex items-center gap-2 text-muted-foreground" data-testid="loading-state">
          <Loader2 className="h-4 w-4 animate-spin" />
          <span>Loading memories...</span>
        </div>
      )}

      {/* Error State */}
      {error && !loading && (
        <div
          className="rounded-lg border border-red-300 bg-red-50 p-4 text-red-800"
          data-testid="error-state"
        >
          <div className="flex items-center gap-2">
            <AlertCircle className="h-4 w-4" />
            <p className="font-medium">Error loading memories</p>
          </div>
          <p className="text-sm mt-1">{error}</p>
        </div>
      )}

      {/* Delete Confirmation Dialog */}
      {confirmDelete && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/50"
          data-testid="delete-confirm-dialog"
        >
          <div className="bg-background rounded-lg border p-6 max-w-md mx-4 shadow-lg">
            <h3 className="font-semibold text-lg mb-2">Delete Memory</h3>
            <p className="text-sm text-muted-foreground mb-1">
              Are you sure you want to delete this memory?
            </p>
            <p className="text-sm bg-muted rounded p-3 mb-4 line-clamp-3">
              {confirmDelete.content}
            </p>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={handleDeleteCancel}>
                Cancel
              </Button>
              <Button variant="destructive" onClick={handleDeleteConfirm} data-testid="confirm-delete-btn">
                Delete
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Results */}
      {!loading && !error && (
        <div data-testid="results-list">
          {results.length === 0 ? (
            <div className="text-center py-12" data-testid="empty-state">
              <p className="text-muted-foreground text-lg">No memories found</p>
              <p className="text-sm text-muted-foreground mt-1">
                Try adjusting your search query or filters.
              </p>
            </div>
          ) : (
            <div className="space-y-3">
              {results.map((memory, idx) => (
                <MemoryCard
                  key={`${memory.content}-${idx}`}
                  memory={memory}
                  onDelete={handleDeleteRequest}
                />
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useRef, useCallback } from "react";
import { Bell } from "lucide-react";
import { Button } from "@/components/ui/button";
import { getNotifications, markRead, markAllRead } from "@/api/notifications";
import type { Notification } from "@/api/types";

function timeAgo(dateStr: string): string {
  const now = Date.now();
  const then = new Date(dateStr).getTime();
  const diff = Math.max(0, now - then);
  const seconds = Math.floor(diff / 1000);
  if (seconds < 60) return "just now";
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  return `${days}d ago`;
}

function typeIcon(type: string): string {
  if (type.includes("completed")) return "✅";
  if (type.includes("failed")) return "❌";
  return "🔔";
}

export function NotificationBell() {
  const [open, setOpen] = useState(false);
  const [items, setItems] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [total, setTotal] = useState(0);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const fetchUnread = useCallback(async () => {
    try {
      const res = await getNotifications({ limit: 50, read: false });
      setUnreadCount(res.total);
    } catch {
      // ignore
    }
  }, []);

  const fetchAll = useCallback(async () => {
    try {
      const res = await getNotifications({ limit: 50 });
      setItems(res.notifications);
      setTotal(res.total);
      setUnreadCount(res.notifications.filter((n) => !n.read).length);
    } catch {
      // ignore
    }
  }, []);

  useEffect(() => {
    fetchUnread();
    const interval = setInterval(fetchUnread, 30_000);
    return () => clearInterval(interval);
  }, [fetchUnread]);

  useEffect(() => {
    if (open) fetchAll();
  }, [open, fetchAll]);

  // Close on outside click
  useEffect(() => {
    function handleClick(e: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    }
    if (open) document.addEventListener("mousedown", handleClick);
    return () => document.removeEventListener("mousedown", handleClick);
  }, [open]);

  const handleMarkAllRead = async () => {
    try {
      await markAllRead();
      setUnreadCount(0);
      setItems((prev) => prev.map((n) => ({ ...n, read: true })));
    } catch {
      // ignore
    }
  };

  const handleMarkRead = async (id: number) => {
    try {
      await markRead(id);
      setItems((prev) => prev.map((n) => (n.id === id ? { ...n, read: true } : n)));
      setUnreadCount((prev) => Math.max(0, prev - 1));
    } catch {
      // ignore
    }
  };

  return (
    <div className="relative" ref={dropdownRef}>
      <Button
        variant="ghost"
        size="icon"
        className="h-8 w-8 relative"
        onClick={() => setOpen((prev) => !prev)}
        data-testid="notification-bell"
      >
        <Bell className="h-4 w-4" />
        {unreadCount > 0 && (
          <span
            className="absolute -top-1 -right-1 flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-[10px] font-bold text-white"
            data-testid="unread-badge"
          >
            {unreadCount > 9 ? "9+" : unreadCount}
          </span>
        )}
      </Button>
      {open && (
        <div className="absolute right-0 top-full mt-2 w-80 max-h-96 overflow-y-auto rounded-md border bg-popover shadow-lg z-50">
          <div className="flex items-center justify-between border-b px-3 py-2">
            <span className="text-sm font-medium">Notifications</span>
            {unreadCount > 0 && (
              <button
                className="text-xs text-blue-600 hover:underline"
                onClick={handleMarkAllRead}
                data-testid="mark-all-read"
              >
                Mark all as read
              </button>
            )}
          </div>
          <div className="divide-y">
            {items.length === 0 && (
              <div className="px-3 py-4 text-center text-sm text-muted-foreground">
                No notifications
              </div>
            )}
            {items.map((n) => (
              <button
                key={n.id}
                className={`w-full text-left px-3 py-2 hover:bg-accent/50 transition-colors ${
                  !n.read ? "bg-accent/20" : ""
                }`}
                onClick={() => {
                  if (!n.read) handleMarkRead(n.id);
                }}
                data-testid={`notification-item-${n.id}`}
              >
                <div className="flex items-start gap-2">
                  <span className="text-sm mt-0.5">{typeIcon(n.type)}</span>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-1">
                      <span className="text-sm font-medium truncate">{n.title}</span>
                      {!n.read && (
                        <span className="h-2 w-2 rounded-full bg-blue-500 flex-shrink-0" />
                      )}
                    </div>
                    <p className="text-xs text-muted-foreground truncate">{n.message}</p>
                    <span className="text-[10px] text-muted-foreground">{timeAgo(n.created_at)}</span>
                  </div>
                </div>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useRef, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { Dialog, DialogContent } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Lightbulb, GitBranch, BookMarked, Play, Search } from "lucide-react";
import { globalSearch } from "@/api/search";
import type {
  GlobalSearchResponse,
  IdeaSearchItem,
  GapSearchItem,
  PaperSearchItem,
  RunSearchItem,
} from "@/api/types";

const STORAGE_KEY = "erock:recent-searches";
const MAX_RECENT = 10;
const DEBOUNCE_MS = 300;

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

function getRecentSearches(): string[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

function addRecentSearch(query: string) {
  const recent = getRecentSearches().filter((s) => s !== query);
  recent.unshift(query);
  localStorage.setItem(STORAGE_KEY, JSON.stringify(recent.slice(0, MAX_RECENT)));
}

export function GlobalSearchDialog({ open, onOpenChange }: Props) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<GlobalSearchResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout>>();
  const navigate = useNavigate();

  // Auto-focus input when dialog opens
  useEffect(() => {
    if (open) {
      // Small delay so the DOM is ready
      const timer = setTimeout(() => inputRef.current?.focus(), 50);
      return () => clearTimeout(timer);
    } else {
      setQuery("");
      setResults(null);
      setLoading(false);
    }
  }, [open]);

  // Debounced search
  const doSearch = useCallback((q: string) => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    if (!q.trim()) {
      setResults(null);
      setLoading(false);
      return;
    }
    setLoading(true);
    debounceRef.current = setTimeout(async () => {
      try {
        const res = await globalSearch(q);
        setResults(res);
      } catch {
        setResults(null);
      } finally {
        setLoading(false);
      }
    }, DEBOUNCE_MS);
  }, []);

  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
  }, []);

  function handleInputChange(value: string) {
    setQuery(value);
    doSearch(value);
  }

  function handleSelect(type: string, id: number) {
    addRecentSearch(query);
    onOpenChange(false);
    switch (type) {
      case "ideas":
        navigate(`/ideas/${id}`);
        break;
      case "gaps":
        navigate(`/gaps/${id}`);
        break;
      case "papers":
        navigate("/literature");
        break;
      case "runs":
        navigate(`/runs/${id}`);
        break;
    }
  }

  function handleRecentClick(recent: string) {
    setQuery(recent);
    doSearch(recent);
  }

  const recentSearches = !query ? getRecentSearches() : [];

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-xl p-0 overflow-hidden">
        <div className="flex items-center border-b px-3">
          <Search className="mr-2 h-4 w-4 shrink-0 text-muted-foreground" />
          <input
            ref={inputRef}
            placeholder="Search ideas, gaps, papers, runs…"
            className="flex h-11 w-full rounded-md bg-transparent py-3 text-sm outline-none placeholder:text-muted-foreground"
            value={query}
            onChange={(e) => handleInputChange(e.target.value)}
          />
        </div>
        <div className="max-h-80 overflow-y-auto px-2 py-2">
          {/* Loading skeletons */}
          {loading && (
            <div className="space-y-2 px-2">
              {Array.from({ length: 4 }).map((_, i) => (
                <div key={i} className="flex items-center gap-3 p-2">
                  <Skeleton className="h-4 w-4 rounded" />
                  <Skeleton className="h-4 flex-1" />
                </div>
              ))}
            </div>
          )}

          {/* Empty state */}
          {!loading && !results && recentSearches.length === 0 && (
            <p className="py-6 text-center text-sm text-muted-foreground">
              Start typing to search…
            </p>
          )}

          {/* Recent searches */}
          {!loading && !results && recentSearches.length > 0 && (
            <div className="px-2">
              <p className="mb-1 text-xs font-medium text-muted-foreground">
                Recent
              </p>
              {recentSearches.map((s) => (
                <button
                  key={s}
                  className="flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-accent text-left"
                  onClick={() => handleRecentClick(s)}
                >
                  <Search className="h-3 w-3 text-muted-foreground" />
                  {s}
                </button>
              ))}
            </div>
          )}

          {/* Results */}
          {!loading && results && results.total === 0 && (
            <p className="py-6 text-center text-sm text-muted-foreground">
              No results found for "{query}"
            </p>
          )}

          {!loading && results && results.total > 0 && (
            <div className="space-y-3 px-2">
              {results.results.ideas && results.results.ideas.items.length > 0 && (
                <ResultGroup
                  label="Ideas"
                  icon={<Lightbulb className="h-4 w-4 text-yellow-500" />}
                  items={results.results.ideas.items.map((item) => ({
                    id: item.id,
                    title: item.title,
                    secondary: `${item.domain} · ${item.overall_score != null ? `Score: ${(item.overall_score * 100).toFixed(0)}%` : 'Not scored'}`,
                  }))}
                  type="ideas"
                  onSelect={handleSelect}
                />
              )}
              {results.results.gaps && results.results.gaps.items.length > 0 && (
                <ResultGroup
                  label="Gaps"
                  icon={<GitBranch className="h-4 w-4 text-blue-500" />}
                  items={results.results.gaps.items.map((item) => ({
                    id: item.id,
                    title: item.title,
                    secondary: `${item.gap_type} · Confidence: ${item.confidence}`,
                  }))}
                  type="gaps"
                  onSelect={handleSelect}
                />
              )}
              {results.results.papers && results.results.papers.items.length > 0 && (
                <ResultGroup
                  label="Papers"
                  icon={<BookMarked className="h-4 w-4 text-green-500" />}
                  items={results.results.papers.items.map((item) => ({
                    id: item.id,
                    title: item.title,
                    secondary: `${item.year} · ${item.venue}`,
                  }))}
                  type="papers"
                  onSelect={handleSelect}
                />
              )}
              {results.results.runs && results.results.runs.items.length > 0 && (
                <ResultGroup
                  label="Runs"
                  icon={<Play className="h-4 w-4 text-purple-500" />}
                  items={results.results.runs.items.map((item) => ({
                    id: item.id,
                    title: `Run #${item.id}`,
                    secondary: `${item.status} · ${item.domain}`,
                  }))}
                  type="runs"
                  onSelect={handleSelect}
                />
              )}
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

interface ResultGroupProps {
  label: string;
  icon: React.ReactNode;
  items: { id: number; title: string; secondary: string }[];
  type: string;
  onSelect: (type: string, id: number) => void;
}

function ResultGroup({ label, icon, items, type, onSelect }: ResultGroupProps) {
  return (
    <div>
      <p className="mb-1 text-xs font-medium text-muted-foreground">{label}</p>
      {items.map((item) => (
        <button
          key={`${type}-${item.id}`}
          className="flex w-full items-center gap-3 rounded-sm px-2 py-1.5 text-sm hover:bg-accent text-left"
          onClick={() => onSelect(type, item.id)}
        >
          {icon}
          <div className="flex-1 min-w-0">
            <div className="truncate font-medium">{item.title}</div>
            <div className="truncate text-xs text-muted-foreground">
              {item.secondary}
            </div>
          </div>
        </button>
      ))}
    </div>
  );
}

import { useState, useEffect } from "react";
import {
  triggerAutonomous,
  getAutonomousHistory,
  stopAutonomousCycle,
  getEvolutionStatus,
  startScheduler,
  stopScheduler,
  getSchedulerStatus,
  type EvolutionStatus,
  type SchedulerStatus,
} from "@/api/autonomous";
import { ConsciousnessStateBadge } from "@/components/autonomous/consciousness-state";
import { CycleProgress } from "@/components/autonomous/cycle-progress";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Cpu, Loader2, AlertCircle, Play, StopCircle, Clock, Activity } from "lucide-react";
import type { AutonomousCycleHistoryEntry, ConsciousnessState } from "@/api/autonomous";

export default function AutonomousPage() {
  const [cycles, setCycles] = useState<AutonomousCycleHistoryEntry[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isStarting, setIsStarting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [domain, setDomain] = useState("AI/NLP");
  const [maxRuns, setMaxRuns] = useState(3);
  const [consciousnessState, setConsciousnessState] = useState<ConsciousnessState>("idle");
  const [stopConfirmId, setStopConfirmId] = useState<string | null>(null);

  // Scheduler + evolution state
  const [schedulerStatus, setSchedulerStatus] = useState<SchedulerStatus | null>(null);
  const [evolutionStatus, setEvolutionStatus] = useState<EvolutionStatus | null>(null);
  const [schedulerLoading, setSchedulerLoading] = useState(false);

  useEffect(() => {
    loadHistory();
    loadSchedulerAndEvolution();
  }, []);

  async function loadHistory() {
    try {
      const data = await getAutonomousHistory();
      setCycles(data.cycles);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load history");
    } finally {
      setIsLoading(false);
    }
  }

  async function loadSchedulerAndEvolution() {
    try {
      const [sched, evo] = await Promise.all([
        getSchedulerStatus(),
        getEvolutionStatus(),
      ]);
      setSchedulerStatus(sched);
      setEvolutionStatus(evo);
    } catch {
      // Non-fatal
    }
  }

  async function handleSchedulerStart() {
    setSchedulerLoading(true);
    setError(null);
    try {
      await startScheduler();
      await loadSchedulerAndEvolution();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to start scheduler");
    } finally {
      setSchedulerLoading(false);
    }
  }

  async function handleSchedulerStop() {
    setSchedulerLoading(true);
    setError(null);
    try {
      await stopScheduler();
      await loadSchedulerAndEvolution();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to stop scheduler");
    } finally {
      setSchedulerLoading(false);
    }
  }

  async function handleStart() {
    setIsStarting(true);
    setError(null);
    try {
      await triggerAutonomous({ domain, max_runs: maxRuns });
      await loadHistory();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to start cycle");
    } finally {
      setIsStarting(false);
    }
  }

  function handleStopRequest(cycleId: string) {
    // HB-01: Require confirmation before stopping
    setStopConfirmId(cycleId);
  }

  async function handleStopConfirm(cycleId: string) {
    setStopConfirmId(null);
    try {
      await stopAutonomousCycle(cycleId);
      await loadHistory();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to stop cycle");
    }
  }

  function handleStopCancel() {
    setStopConfirmId(null);
  }

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4" data-testid="autonomous-loading">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
        <p className="text-muted-foreground">Loading autonomous cycles...</p>
      </div>
    );
  }

  return (
    <div className="space-y-6" data-testid="autonomous-page">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Autonomous Cycles</h1>
          <p className="text-muted-foreground">Monitor and control autonomous research cycles.</p>
        </div>
        <div data-testid="consciousness-display">
          <ConsciousnessStateBadge state={consciousnessState} />
        </div>
      </div>

      {error && (
        <Card className="border-destructive" data-testid="autonomous-error">
          <CardContent className="p-4 flex items-center gap-2">
            <AlertCircle className="h-4 w-4 text-destructive" />
            <span className="text-sm text-destructive">{error}</span>
          </CardContent>
        </Card>
      )}

      {/* Start Cycle Form */}
      <Card data-testid="autonomous-start-form">
        <CardHeader>
          <CardTitle className="text-lg">Start New Cycle</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-end gap-4">
            <div className="flex-1">
              <label className="text-sm font-medium" data-testid="domain-label">Domain</label>
              <input
                type="text"
                value={domain}
                onChange={(e) => setDomain(e.target.value)}
                className="mt-1 w-full rounded-md border px-3 py-2 text-sm"
                data-testid="domain-input"
              />
            </div>
            <div className="w-32">
              <label className="text-sm font-medium">Max Runs</label>
              <input
                type="number"
                value={maxRuns}
                onChange={(e) => setMaxRuns(Number(e.target.value))}
                min={1}
                max={20}
                className="mt-1 w-full rounded-md border px-3 py-2 text-sm"
                data-testid="max-runs-input"
              />
            </div>
            <Button
              onClick={handleStart}
              disabled={isStarting}
              data-testid="start-cycle-btn"
            >
              {isStarting ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : (
                <Play className="h-4 w-4 mr-2" />
              )}
              {isStarting ? "Starting..." : "Start Cycle"}
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Scheduler Controls */}
      <Card data-testid="scheduler-controls">
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <Clock className="h-4 w-4" />
            Scheduler
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center gap-2 text-sm">
            <span className="font-medium">Status:</span>
            <span data-testid="scheduler-status-text">
              {schedulerStatus?.status ?? "unknown"}
            </span>
          </div>
          {schedulerStatus?.status === "running" && schedulerStatus.next_run && (
            <div className="flex items-center gap-2 text-sm">
              <span className="font-medium">Next Run:</span>
              <span>{new Date(schedulerStatus.next_run).toLocaleString()}</span>
            </div>
          )}
          <div className="flex items-center gap-3">
            <Button
              onClick={handleSchedulerStart}
              disabled={schedulerLoading || schedulerStatus?.status === "running"}
              variant="outline"
              data-testid="scheduler-start-btn"
            >
              {schedulerLoading ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : <Play className="h-4 w-4 mr-2" />}
              Start Scheduler
            </Button>
            <Button
              onClick={handleSchedulerStop}
              disabled={schedulerLoading || schedulerStatus?.status !== "running"}
              variant="destructive"
              data-testid="scheduler-stop-btn"
            >
              <StopCircle className="h-4 w-4 mr-2" />
              Stop Scheduler
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Evolution Status */}
      <Card data-testid="evolution-status-card">
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <Activity className="h-4 w-4" />
            Evolution Status
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-2 text-sm">
            <div className="flex items-center gap-2">
              <span className="font-medium">Enabled:</span>
              <span data-testid="evolution-enabled">
                {evolutionStatus?.enabled ? "Yes" : "No"}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <span className="font-medium">Overlays:</span>
              <span data-testid="evolution-overlays">
                {evolutionStatus?.overlays_generated ?? 0}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <span className="font-medium">Recent Outcomes:</span>
              <span data-testid="evolution-outcomes">
                {evolutionStatus?.recent_outcomes?.length ?? 0}
              </span>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Stop Confirmation (HB-01) */}
      {stopConfirmId && (
        <Card className="border-yellow-500" data-testid="stop-confirm-dialog">
          <CardContent className="p-4">
            <p className="text-sm font-medium mb-3">
              Are you sure you want to stop cycle <code className="text-xs">{stopConfirmId}</code>?
            </p>
            <div className="flex gap-2">
              <Button
                variant="destructive"
                size="sm"
                onClick={() => handleStopConfirm(stopConfirmId)}
                data-testid="stop-confirm-btn"
              >
                <StopCircle className="h-4 w-4 mr-1" />
                Confirm Stop
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={handleStopCancel}
                data-testid="stop-cancel-btn"
              >
                Cancel
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* History List */}
      <div>
        <h2 className="text-lg font-semibold mb-3" data-testid="history-heading">Cycle History</h2>
        {cycles.length === 0 ? (
          <Card data-testid="autonomous-empty">
            <CardContent className="p-8 flex flex-col items-center gap-4">
              <Cpu className="h-12 w-12 text-muted-foreground" />
              <p className="text-muted-foreground">No autonomous cycles yet. Start one above.</p>
            </CardContent>
          </Card>
        ) : (
          <div className="space-y-3" data-testid="autonomous-history-list">
            {cycles.map((cycle) => (
              <CycleProgress
                key={cycle.cycle_id}
                cycle={cycle}
                onStop={handleStopRequest}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * CostsPage — BATCH-18/TASK-03
 *
 * Full Cost Dashboard page replacing the /costs placeholder.
 * Shows: total spend summary, cost breakdowns by provider/stage/model,
 * per-run cost list, and budget utilization bar.
 */

import { useEffect, useState } from "react";
import {
  getCostSummary,
  getCostByProvider,
  getCostByStage,
  getCostByModel,
  getRunCostBreakdown,
} from "@/api/costs";
import type {
  CostSummary,
  ProviderBreakdown,
  StageBreakdown,
  ModelBreakdown,
  RunCostBreakdown,
} from "@/api/costs";
import { CostSummaryCard } from "@/components/costs/cost-summary-card";
import { CostBreakdownTable } from "@/components/costs/cost-breakdown-table";
import { BudgetBar } from "@/components/costs/budget-bar";

/** Default budget limit in USD (matches backend budget_max_cost_usd default) */
const DEFAULT_BUDGET_LIMIT = 10.0;

export default function CostsPage() {
  const [summary, setSummary] = useState<CostSummary | null>(null);
  const [byProvider, setByProvider] = useState<ProviderBreakdown>({});
  const [byStage, setByStage] = useState<StageBreakdown>({});
  const [byModel, setByModel] = useState<ModelBreakdown>({});
  const [runCosts, setRunCosts] = useState<RunCostBreakdown[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;

    async function load() {
      try {
        const [sum, prov, stage, model] = await Promise.all([
          getCostSummary(),
          getCostByProvider(),
          getCostByStage(),
          getCostByModel(),
        ]);
        if (cancelled) return;

        setSummary(sum);
        setByProvider(prov);
        setByStage(stage);
        setByModel(model);
        setError(null);
      } catch (err) {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : "Failed to load cost data");
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    load();
    return () => { cancelled = true; };
  }, []);

  async function handleLoadRun(runId: string) {
    try {
      const data = await getRunCostBreakdown(runId);
      setRunCosts((prev) => [...prev, data]);
    } catch {
      // Silently ignore — run data is optional
    }
  }

  const currentSpend = summary?.total_cost_usd ?? 0;

  if (loading) {
    return (
      <div className="space-y-6" data-testid="costs-page">
        <h1 className="text-2xl font-bold tracking-tight">Cost Dashboard</h1>
        <p className="text-muted-foreground">Loading cost data…</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="space-y-6" data-testid="costs-page">
        <h1 className="text-2xl font-bold tracking-tight">Cost Dashboard</h1>
        <div className="rounded-lg border border-red-300 bg-red-50 p-4 text-red-800" data-testid="cost-error">
          <p className="font-medium">Error loading cost data</p>
          <p className="text-sm">{error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6" data-testid="costs-page">
      <h1 className="text-2xl font-bold tracking-tight">Cost Dashboard</h1>

      {/* Summary + Budget */}
      <div className="grid gap-6 md:grid-cols-2">
        <div data-testid="cost-summary-section">
          {summary && <CostSummaryCard summary={summary} />}
        </div>
        <div data-testid="budget-section">
          <BudgetBar currentSpend={currentSpend} budgetLimit={DEFAULT_BUDGET_LIMIT} />
        </div>
      </div>

      {/* Breakdown tables */}
      <div className="grid gap-6 lg:grid-cols-2" data-testid="cost-breakdown-section">
        <CostBreakdownTable
          title="Cost by Provider"
          data={byProvider}
          labelColumn="Provider"
        />
        <CostBreakdownTable
          title="Cost by Stage"
          data={byStage}
          labelColumn="Stage"
        />
      </div>

      <CostBreakdownTable
        title="Cost by Model"
        data={byModel}
        labelColumn="Model"
      />

      {/* Per-run cost list */}
      <div data-testid="run-costs-section">
        <div className="rounded-lg border bg-card p-6">
          <h3 className="text-sm font-medium text-muted-foreground mb-4">
            Per-Run Cost Breakdown
          </h3>
          {runCosts.length === 0 ? (
            <p className="text-sm text-muted-foreground">
              No run cost data loaded. Use the run ID lookup below.
            </p>
          ) : (
            <div className="space-y-4">
              {runCosts.map((rc) => (
                <div key={rc.run_id} className="border rounded-lg p-4">
                  <p className="font-medium mb-2">Run: {rc.run_id}</p>
                  <p className="text-sm text-muted-foreground">
                    Total: ${rc.summary.total_cost_usd.toFixed(4)} —{" "}
                    {rc.summary.event_count} events
                  </p>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * KnowledgeGraphPage — interactive graph explorer.
 *
 * Features: stats bar, type filter, search, SVG graph canvas, entity detail panel.
 * HB-02: Initial render limited to 100 entities.
 */

import { useCallback, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { BrainCircuit, Search, Filter, Loader2 } from "lucide-react";
import { getGraphStats, getEntities, getEntity, getWorldModel } from "@/api/knowledge-graph";
import type { GraphStats, GraphEntity, EntityDetail, WorldModel } from "@/api/knowledge-graph";
import { GraphCanvas } from "@/components/knowledge-graph/graph-canvas";
import { EntityDetail as EntityDetailPanel } from "@/components/knowledge-graph/entity-detail";
import { WorldModelPanel } from "@/components/knowledge-graph/world-model-panel";

const ENTITY_TYPES = ["paper", "author", "method", "dataset", "concept"];

export default function KnowledgeGraphPage() {
  const [searchTerm, setSearchTerm] = useState("");
  const [typeFilter, setTypeFilter] = useState<string>("");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [detailData, setDetailData] = useState<EntityDetail | null>(null);

  // ── World model query ────────────────────────────────────────
  const { data: worldModel } = useQuery({
    queryKey: ["knowledge-graph-world-model"],
    queryFn: () => getWorldModel(),
  });

  // ── Stats query ───────────────────────────────────────────────
  const { data: stats, isLoading: statsLoading } = useQuery({
    queryKey: ["knowledge-graph-stats"],
    queryFn: () => getGraphStats(),
  });

  // ── Entities query (HB-02: max 100) ──────────────────────────
  const { data: entities, isLoading: entitiesLoading } = useQuery({
    queryKey: ["knowledge-graph-entities", typeFilter, searchTerm],
    queryFn: () =>
      getEntities({
        type: typeFilter || undefined,
        search: searchTerm || undefined,
        limit: 100,
      }),
  });

  // ── Derive relationships from entity detail for the canvas ───
  const relationships = detailData?.relationships || [];

  // ── Entity detail query ──────────────────────────────────────
  const handleSelectEntity = useCallback(
    async (id: string) => {
      setSelectedId(id);
      try {
        const detail = await getEntity(id);
        setDetailData(detail);
      } catch {
        // Silently handle — detail panel stays hidden
      }
    },
    [],
  );

  const handleCloseDetail = useCallback(() => {
    setSelectedId(null);
    setDetailData(null);
  }, []);

  const handleNavigateToEntity = useCallback(
    (id: string) => {
      handleSelectEntity(id);
    },
    [handleSelectEntity],
  );

  const isLoading = statsLoading || entitiesLoading;

  return (
    <div className="space-y-4">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
          <BrainCircuit className="h-6 w-6" />
          Knowledge Graph
        </h1>
        <p className="text-muted-foreground">
          Explore entities and their relationships in the knowledge graph.
        </p>
      </div>

      {/* Stats Bar */}
      {stats && (
        <div className="flex gap-4 text-sm">
          <span className="px-3 py-1 rounded-md bg-primary/10 text-primary font-medium">
            {stats.entity_count} entities
          </span>
          <span className="px-3 py-1 rounded-md bg-primary/10 text-primary font-medium">
            {stats.relationship_count} relationships
          </span>
          {Object.entries(stats.entity_types).map(
            ([type, count]) =>
              count > 0 && (
                <span key={type} className="px-2 py-1 rounded-md bg-muted text-muted-foreground">
                  {type}: {count}
                </span>
              ),
          )}
        </div>
      )}

      {/* World Model Panel */}
      {worldModel && (
        <WorldModelPanel model={worldModel} />
      )}

      {/* Filters */}
      <div className="flex gap-3 items-center">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
          <input
            type="text"
            placeholder="Search entities..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-9 pr-3 py-2 text-sm border rounded-md bg-background"
          />
        </div>
        <div className="flex items-center gap-1.5">
          <Filter className="h-4 w-4 text-muted-foreground" />
          <select
            value={typeFilter}
