              className="h-[500px]"
            />
          </div>

          {/* Entity Detail Panel */}
          {detailData && (
            <div className="lg:col-span-1">
              <EntityDetailPanel
                detail={detailData}
                onClose={handleCloseDetail}
                onNavigateToEntity={handleNavigateToEntity}
              />
            </div>
          )}
        </div>
      ) : (
        <div className="text-center py-12 text-muted-foreground">
          <BrainCircuit className="h-8 w-8 mx-auto mb-2 opacity-50" />
          <p>No entities found. Ingest papers to populate the knowledge graph.</p>
        </div>
      )}
    </div>
  );
}

/**
 * TracesPage — BATCH-21/TASK-02
 *
 * Traces viewer page replacing /traces placeholder.
 * Shows: summary stats, latency metrics, trace list, and span detail on click.
 */

import { useEffect, useState, useCallback } from "react";
import {
  getTraceSummary,
  getTrace,
  getTraceMetrics,
} from "@/api/traces";
import type {
  TraceSummary as TraceSummaryData,
  TraceDetail,
  TraceMetrics as TraceMetricsData,
} from "@/api/traces";
import { TraceSummary } from "@/components/traces/trace-summary";
import { SpanDetail } from "@/components/traces/span-detail";

export default function TracesPage() {
  const [summary, setSummary] = useState<TraceSummaryData | null>(null);
  const [metrics, setMetrics] = useState<TraceMetricsData | null>(null);
  const [selectedTrace, setSelectedTrace] = useState<TraceDetail | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [serviceUnavailable, setServiceUnavailable] = useState(false);

  useEffect(() => {
    let cancelled = false;

    async function load() {
      try {
        const [sum, met] = await Promise.all([
          getTraceSummary(),
          getTraceMetrics(),
        ]);
        if (cancelled) return;

        setSummary(sum);
        setMetrics(met);
        setError(null);
        setServiceUnavailable(false);
      } catch (err) {
        if (cancelled) return;
        const message = err instanceof Error ? err.message : "Failed to load trace data";
        if (message.toLowerCase().includes("observability not enabled") ||
            message.toLowerCase().includes("service unavailable")) {
          setServiceUnavailable(true);
        }
        setError(message);
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    load();
    return () => { cancelled = true; };
  }, []);

  const handleTraceClick = useCallback(async (traceId: string) => {
    try {
      const detail = await getTrace(traceId);
      setSelectedTrace(detail);
    } catch {
      // Silently ignore — span detail is optional
    }
  }, []);

  const formatDuration = (ms: number): string => {
    if (ms >= 1000) return `${(ms / 1000).toFixed(2)}s`;
    return `${ms.toFixed(0)}ms`;
  };

  if (loading) {
    return (
      <div className="space-y-6" data-testid="traces-page">
        <h1 className="text-2xl font-bold tracking-tight">Traces</h1>
        <p className="text-muted-foreground" data-testid="traces-loading">Loading trace data…</p>
      </div>
    );
  }

  if (serviceUnavailable) {
    return (
      <div className="space-y-6" data-testid="traces-page">
        <h1 className="text-2xl font-bold tracking-tight">Traces</h1>
        <div className="rounded-lg border border-yellow-300 bg-yellow-50 p-4 text-yellow-800" data-testid="traces-service-unavailable">
          <p className="font-medium">Observability Not Enabled</p>
          <p className="text-sm">Enable observability in platform configuration to view traces.</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="space-y-6" data-testid="traces-page">
        <h1 className="text-2xl font-bold tracking-tight">Traces</h1>
        <div className="rounded-lg border border-red-300 bg-red-50 p-4 text-red-800" data-testid="traces-error">
          <p className="font-medium">Error loading trace data</p>
          <p className="text-sm">{error}</p>
        </div>
      </div>
    );
  }

  const isEmpty = summary !== null && summary.total_traces === 0;

  return (
    <div className="space-y-6" data-testid="traces-page">
      <h1 className="text-2xl font-bold tracking-tight">Traces</h1>

      {/* Summary stats */}
      {summary && (
        <div data-testid="traces-summary-section">
          <TraceSummary summary={summary} />
        </div>
      )}

      {/* Latency metrics */}
      {metrics && (
        <div className="rounded-lg border bg-card p-6" data-testid="traces-metrics">
          <h3 className="text-sm font-medium text-muted-foreground mb-4">Latency Metrics</h3>
          <div className="grid gap-4 sm:grid-cols-3">
            <div>
              <p className="text-2xl font-bold" data-testid="metric-p50">
                {formatDuration(metrics.p50_ms)}
              </p>
              <p className="text-sm text-muted-foreground">P50 Latency</p>
            </div>
            <div>
              <p className="text-2xl font-bold" data-testid="metric-p99">
                {formatDuration(metrics.p99_ms)}
              </p>
              <p className="text-sm text-muted-foreground">P99 Latency</p>
            </div>
            <div>
              <p className="text-2xl font-bold" data-testid="metric-error-rate">
                {(metrics.error_rate * 100).toFixed(1)}%
              </p>
              <p className="text-sm text-muted-foreground">Error Rate</p>
            </div>
          </div>
        </div>
      )}

      {/* Empty state */}
      {isEmpty && (
        <div className="rounded-lg border bg-card p-6 text-center" data-testid="traces-empty">
          <p className="text-muted-foreground">No traces recorded yet. Run a pipeline to generate traces.</p>
        </div>
      )}

      {/* Trace list — shows active + recent traces */}
      {summary && !isEmpty && (
        <div data-testid="traces-list">
          <div className="rounded-lg border bg-card p-6">
            <h3 className="text-sm font-medium text-muted-foreground mb-4">Recent Traces</h3>
            <div className="space-y-2">
              {Array.from({ length: summary.total_traces }, (_, i) => {
                const traceId = `trace-${i + 1}`;
                const isActive = i < summary.active_traces;
                return (
                  <button
                    key={traceId}
                    className="flex w-full items-center justify-between rounded-md border px-4 py-2 text-left hover:bg-accent transition-colors"
                    data-testid={`trace-item-${traceId}`}
                    onClick={() => handleTraceClick(traceId)}
                  >
                    <span className="text-sm font-medium font-mono">{traceId}</span>
                    {isActive && (
                      <span className="text-xs px-2 py-0.5 rounded-full bg-green-100 text-green-800">
                        Active
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      )}

      {/* Span detail — shown when a trace is selected */}
      {selectedTrace && (
        <div data-testid="traces-span-detail">
          <SpanDetail spans={selectedTrace.spans} traceId={selectedTrace.trace_id} />
        </div>
      )}
    </div>
  );
}

import { Component, type ReactNode } from "react";
import { Sentry } from "@/lib/sentry";

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false, error: null };

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error("ErrorBoundary caught:", error, info.componentStack);
    try {
      Sentry.captureException(error);
    } catch {
      // Sentry not initialized — ignore
    }
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="flex items-center justify-center min-h-[50vh] p-8">
          <div className="max-w-md text-center space-y-4">
            <h2 className="text-xl font-bold">Something went wrong</h2>
            <p className="text-sm text-muted-foreground">
              {this.state.error?.message || "An unexpected error occurred."}
            </p>
            <button
              onClick={() => {
                this.setState({ hasError: false, error: null });
                window.location.reload();
              }}
              className="rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:bg-primary/90"
            >
              Reload
            </button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { getSessionList } from "@/api/sessions";
import { listRuns } from "@/api/pipeline";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import type { SessionGroup, PipelineRunSummary } from "@/api/types";
import { Layers, Loader2, AlertCircle, ChevronRight } from "lucide-react";

export default function SessionsPage() {
  const navigate = useNavigate();
  const [sessions, setSessions] = useState<SessionGroup[]>([]);
  const [selectedSession, setSelectedSession] = useState<string | null>(null);
  const [runs, setRuns] = useState<PipelineRunSummary[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isRunsLoading, setIsRunsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      try {
        const data = await getSessionList();
        setSessions(data.sessions);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to load sessions");
      } finally {
        setIsLoading(false);
      }
    }
    load();
  }, []);

  async function handleSelectSession(sessionId: string) {
    setSelectedSession(sessionId);
    setIsRunsLoading(true);
    try {
      const data = await listRuns({ session_id: sessionId, limit: 50 });
      setRuns(data.runs);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load runs");
    } finally {
      setIsRunsLoading(false);
    }
  }

  function formatDate(dateStr: string) {
    try {
      return new Date(dateStr).toLocaleString();
    } catch {
      return dateStr;
    }
  }

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4" data-testid="sessions-loading">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
        <p className="text-muted-foreground">Loading sessions...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4" data-testid="sessions-error">
        <AlertCircle className="h-8 w-8 text-destructive" />
        <p className="text-destructive font-medium">Error loading sessions</p>
        <p className="text-muted-foreground text-sm">{error}</p>
      </div>
    );
  }

  if (sessions.length === 0 && !selectedSession) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4" data-testid="sessions-empty">
        <Layers className="h-12 w-12 text-muted-foreground" />
        <h1 className="text-2xl font-bold tracking-tight">Sessions</h1>
        <p className="text-muted-foreground">No sessions yet. Start a pipeline run with a session ID to see grouped results here.</p>
      </div>
    );
  }

  return (
    <div className="space-y-6" data-testid="sessions-page">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Sessions</h1>
        <p className="text-muted-foreground">Pipeline runs grouped by session ID.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Session List */}
        <div className="lg:col-span-1 space-y-3">
          {sessions.map((session) => (
            <Card
              key={session.session_id}
              className={`cursor-pointer hover:bg-accent/50 transition-colors ${
                selectedSession === session.session_id ? "ring-2 ring-primary" : ""
              }`}
              onClick={() => handleSelectSession(session.session_id)}
              data-testid={`session-card-${session.session_id}`}
            >
              <CardContent className="p-4">
                <div className="flex items-center justify-between">
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-medium truncate" data-testid={`session-name-${session.session_id}`}>
                      {session.session_id}
                    </p>
                    <div className="flex items-center gap-2 mt-1">
                      <Badge variant="secondary" data-testid={`session-count-${session.session_id}`}>
                        {session.run_count} run{session.run_count !== 1 ? "s" : ""}
                      </Badge>
                      <span className="text-xs text-muted-foreground" data-testid={`session-date-${session.session_id}`}>
                        {formatDate(session.latest_run_at)}
                      </span>
                    </div>
                  </div>
                  <ChevronRight className="h-4 w-4 text-muted-foreground shrink-0" />
                </div>
              </CardContent>
            </Card>
          ))}
        </div>

        {/* Run List for Selected Session */}
        <div className="lg:col-span-2">
          {selectedSession ? (
            <div className="space-y-4">
              <div className="flex items-center gap-2">
                <CardTitle className="text-lg">{selectedSession}</CardTitle>
                <Badge variant="outline">{runs.length} run{runs.length !== 1 ? "s" : ""}</Badge>
              </div>

              {isRunsLoading ? (
                <div className="flex items-center gap-2 p-4" data-testid="sessions-runs-loading">
                  <Loader2 className="h-4 w-4 animate-spin" />
                  <span className="text-sm text-muted-foreground">Loading runs...</span>
                </div>
              ) : (
                <div className="space-y-3" data-testid="sessions-runs-list">
                  {runs.map((run) => (
                    <Card
                      key={run.id}
                      className="cursor-pointer hover:bg-accent/50 transition-colors"
                      onClick={() => navigate(`/runs/${run.id}`)}
                      data-testid={`session-run-${run.id}`}
                    >
                      <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                          <div>
                            <p className="text-sm font-medium">Run #{run.id}</p>
                            <p className="text-xs text-muted-foreground">{run.domain}</p>
                          </div>
                          <div className="flex items-center gap-2">
                            <Badge
                              className={
                                run.status === "completed"
                                  ? "bg-green-100 text-green-800"
                                  : run.status === "failed"
                                  ? "bg-red-100 text-red-800"
                                  : run.status === "running"
                                  ? "bg-blue-100 text-blue-800"
                                  : "bg-gray-100 text-gray-800"
                              }
                            >
                              {run.status}
                            </Badge>
                            {run.ideas_count > 0 && (
                              <Badge variant="secondary">{run.ideas_count} ideas</Badge>
                            )}
                            <span className="text-xs text-muted-foreground">
                              {formatDate(run.created_at)}
                            </span>
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              )}
            </div>
          ) : (
            <div className="flex items-center justify-center min-h-[40vh] text-muted-foreground">
              <p>Select a session to view its runs</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

